(()=>{var a=/^file:\/\/\/[^?#]*\.(md|markdown|mdown|mkd)(\?.*)?$/i;chrome.runtime.onMessage.addListener((o,t,e)=>{if(!o||o.type!=="read-file")return;let i=String(t.url||"").split("#")[0];if(t.id!==chrome.runtime.id||!t.tab||t.frameId!==0||!a.test(i)){e({ok:!1,error:"lecture non autoris\xE9e"});return}return fetch(i,{cache:"no-store"}).then(r=>r.text()).then(r=>e({ok:!0,text:r}),r=>e({ok:!1,error:r.message})),!0});})();
